const fs = require('fs');
const BS = '\\';
const punct = ['!','"','#','$','%','&',"'",'(',')','*','+',',','-','.','/',':',';','<','=','>','?','@','[',BS,']','^','_','`','{','|','}','~'];
const lines = [];
const add = (label, text) => lines.push(JSON.stringify({ label, text }));
for (const c of punct) add('mid_' + c, 'x' + BS + c + 'y');
for (const c of punct) add('alone_' + c, BS + c);
for (const c of ['a', 'Z', '0', '9', ' ', '\t']) add('nonpunct_' + JSON.stringify(c), 'x' + BS + c + 'y');
add('bs_nl', 'x' + BS + '\ny');
add('bs_end', 'x' + BS);
add('bs_bs', 'x' + BS + BS + 'y');
add('bs_bs_star', 'a' + BS + BS + '*b*c');
add('bs_star', 'a' + BS + '*b*c');
